-- `(date, timestamp, text)` with 2 677 characters is refused: the timestamp is aligned to
-- 8 after the 4-byte date.
-- @setup
CREATE TABLE t (d date, s timestamp, a text);
CREATE INDEX t_i ON t (d, s, a);
-- @test
-- @expect-error: temporal parts and a text part over the limit
-- @expect-message
-- @profile-lock
INSERT INTO t VALUES ('2020-01-01', '2020-01-01 00:00:00', '');
